SPECIALIZATION_SM103_WS8_MID = "sm103_ws8_mid"
SPECIALIZATION_WIDE_MLP = "wide_mlp"
# Reviewed shape specializations of the union, keyed by (arch, world_size,
# dtype, launch_with_pdl, tokens, active experts) and filled mechanically from
# the exported routes.  Every other configuration runs the generic schedule of
# its (arch, world_size, dtype, launch_with_pdl) tuple.
